"use client";

import {
  Label,
  Slider as AriaSlider,
  SliderOutput,
  SliderThumb,
  SliderTrack,
  type SliderProps as AriaSliderProps,
} from "react-aria-components";
import { sliderDefaults, type SliderSpecProps } from "../generated/slider.types";
import { cx } from "../utils/cx";
import { fieldLabel } from "../utils/field";

export interface SliderProps
  extends SliderSpecProps,
    Omit<AriaSliderProps<number | number[]>, keyof SliderSpecProps | "className" | "children"> {
  className?: string;
}

const thumb =
  "top-1/2 size-5 rounded-full border-2 border-[var(--rd-color-action-primary)] bg-[var(--rd-color-surface-raised)] [box-shadow:var(--rd-elevation-raised)] outline-none " +
  "transition-[box-shadow,transform] data-[dragging]:scale-110 data-[dragging]:[box-shadow:var(--rd-elevation-floating)] data-[focus-visible]:ring-4 data-[focus-visible]:ring-[var(--rd-color-focus-ring)] " +
  "data-[disabled]:border-[var(--rd-color-border-strong)]";

export function Slider({
  label,
  minValue = sliderDefaults.minValue,
  maxValue = sliderDefaults.maxValue,
  step = sliderDefaults.step,
  showValue = sliderDefaults.showValue,
  isDisabled = sliderDefaults.isDisabled,
  className,
  ...rest
}: SliderProps) {
  return (
    <AriaSlider
      {...rest}
      minValue={minValue}
      maxValue={maxValue}
      step={step}
      isDisabled={isDisabled}
      className={cx("group flex w-full flex-col gap-2", className)}
    >
      <div className="flex items-baseline justify-between gap-4">
        {/* Disabled dims only the track and thumb: the label and value stay
            readable (muted, still 4.5:1), so people know what the setting is. */}
        <Label className={cx(fieldLabel, "group-data-[disabled]:text-[var(--rd-color-text-muted)]")}>{label}</Label>
        {showValue && (
          // Ranges show "min – max" with the locale's formatting.
          <SliderOutput className="text-sm tabular-nums text-[var(--rd-color-text-muted)]">
            {({ state }) => state.values.map((_, i) => state.getThumbValueLabel(i)).join(" – ")}
          </SliderOutput>
        )}
      </div>
      <SliderTrack className="relative h-6 w-full group-data-[disabled]:opacity-50">
        {({ state }) => {
          const range = state.values.length > 1;
          const start = range ? state.getThumbPercent(0) : 0;
          const end = state.getThumbPercent(range ? 1 : 0);
          return (
            <>
              <div className="absolute top-1/2 h-1.5 w-full -translate-y-1/2 rounded-full border border-[var(--rd-color-border-default)] bg-[var(--rd-color-surface-subtle)]" />
              <div
                className="absolute top-1/2 h-1.5 -translate-y-1/2 rounded-full bg-[var(--rd-color-action-primary)] group-data-[disabled]:bg-[var(--rd-color-border-strong)]"
                style={{ insetInlineStart: `${start * 100}%`, width: `${(end - start) * 100}%` }}
              />
              {state.values.map((_, i) => (
                <SliderThumb key={i} index={i} className={thumb} aria-label={range ? (i === 0 ? "Minimum" : "Maximum") : undefined} />
              ))}
            </>
          );
        }}
      </SliderTrack>
    </AriaSlider>
  );
}

// Generated by rdloom codegen from specs/slider.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

/** Picks a number, or a range with two thumbs, by dragging along a track. Shows the formatted value. */
export interface SliderSpecProps {
  /**
   * Visible label, also the accessible name.
   */
  label: string;
  /**
   * Lowest value.
   * @default 0
   */
  minValue?: number;
  /**
   * Highest value.
   * @default 100
   */
  maxValue?: number;
  /**
   * Amount each arrow key press changes the value by.
   * @default 1
   */
  step?: number;
  /**
   * Controlled value. An array of two numbers makes a range slider.
   */
  value?: number | number[];
  /**
   * Initial value when uncontrolled. An array of two numbers makes a range slider.
   */
  defaultValue?: number | number[];
  /**
   * How the value is shown and announced, e.g. { style: 'currency', currency: 'USD' }.
   */
  formatOptions?: Intl.NumberFormatOptions;
  /**
   * Shows the formatted value next to the label.
   * @default true
   */
  showValue?: boolean;
  /**
   * Prevents interaction and dims the slider.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Called continuously while the value changes.
   */
  onChange?: (value: number | number[]) => void;
  /**
   * Called once when the user finishes, e.g. to run a search.
   */
  onChangeEnd?: (value: number | number[]) => void;
}

export const sliderDefaults = {
  minValue: 0,
  maxValue: 100,
  step: 1,
  showValue: true,
  isDisabled: false,
} as const;

export const sliderMeta = {
  "name": "Slider",
  "version": "0.1.0",
  "status": "experimental",
  "role": "slider"
} as const;
